    describe('XML to Fluent', () => {
        test.skip('Sync Action with various inputs/outputs', async () => {
            const project = ctx.createProject()
            const { changedFiles } = await project.transform(
                '../xml/sys_hub_action_type_definition_608d2f045947479bb9f212181bbfc996.xml'
            )

            expect(changedFiles).toHaveLength(1)
            const file = changedFiles[0]
            expect(file).toBeDefined()
            expect(file.getName()).toBe('sys_hub_action_type_definition_608d2f045947479bb9f212181bbfc996.now.ts')

            // expect(file.getContent()).toBe(loadTestFile('result.now.ts', 'sync'))
        })

        /**
         * Tests that when ActionDefinitionPlugin.toShape returns { success: false },
         * the XML to Fluent transformation falls back to generating Record API code
         * instead of ActionDefinition() code.
         *
         * The toShape function is currently disabled (returns false) to prevent
         * generating ActionDefinition code until the feature is fully ready.
         * This test verifies that the fallback to Record API works correctly.
         */
        test('ActionDefinition toShape returns false - falls back to Record API', async () => {
            const project = ctx.createProject()

            // Transform the Send Email action definition XML
            const { changedFiles } = await project.transform(
                '../xml/sys_hub_action_type_definition_2d381f4ea32312107ee9d8b8651e61d8.xml'
            )

            // XML contains multiple related records, find the main action definition file
            expect(changedFiles.length).toBeGreaterThan(0)

            const actionDefFile = changedFiles.find((f) => f.getName().startsWith('sys_hub_action_type_definition_'))
            expect(actionDefFile).toBeDefined()
            expect(actionDefFile?.getName()).toBe(
                'sys_hub_action_type_definition_2d381f4ea32312107ee9d8b8651e61d8.now.ts'
            )

            const content = actionDefFile?.getContent()

            // Should NOT contain ActionDefinition() since toShape returns false
            expect(content).not.toContain('ActionDefinition(')

            // Should contain Record API fallback - imported from @servicenow/sdk/core
            expect(content).toContain("import { Record } from '@servicenow/sdk/core'")
            expect(content).toContain('Record({')
            expect(content).toContain("table: 'sys_hub_action_type_definition'")

            // Verify it contains the action's key properties from the XML
            expect(content).toContain('2d381f4ea32312107ee9d8b8651e61d8') // sys_id
            expect(content).toContain("internal_name: 'send_email'") // internal_name
            expect(content).toContain("name: 'Send Email'") // display name
        })

        /**
         * Tests that the sync process correctly handles type changes between FlowObject and FlowArray.
         *
         * This test verifies that when an action definition is updated in ServiceNow:
         * - A FlowArray input can be changed to a FlowObject
         * - A FlowObject input can be changed to a FlowArray
         *
         * After syncing with the XML from ServiceNow, the types are swapped:
         * - flow_array becomes a FlowObject with child_one and child_two fields
         * - flow_object becomes a FlowArray with StringColumn elementType
         *
         * This ensures the sync process correctly parses the attributes object and uses
         * the uiType field to determine whether to build a FlowObject or FlowArray.
         */
        test.skip('Updating flow object to flow array or flow array to flow object should work ', async () => {
            const project = ctx.createProject()
            const fileContent = loadTestFile('action-def.now.ts', 'sync')
            project.addFile({ path: 'action-def.now.ts', content: fileContent })
            const { changedFiles } = await project.transform(
                '../xml/sys_hub_action_type_definition_7f6d4a28ffbcf6103c50ffffffffff69.xml'
            )

            expect(changedFiles).toHaveLength(1)
            const changedFile = changedFiles[0]
            expect(changedFile).toBeDefined()
            expect(changedFile.getName()).toBe('action-def.now.ts')

            expect(changedFile.getContent()).toBe(loadTestFile('action-def-result.now.ts', 'sync'))
        })
    })

